const item = $input.first().json;

// Generate a 6-char base36 ref code using crypto
const array = new Uint32Array(1);
crypto.getRandomValues(array);
const refCode = array[0].toString(36).padStart(6, '0').slice(-6);

// Slugify helper - mirrors blog CMS slug logic
function slugify(s) {
  return String(s || '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '') // strip combining diacritics
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '')
    .slice(0, 60);
}

const titleSlug = item.intentType === 'event'
  ? slugify(item.extracted.title_de || item.extracted.title_en || 'event')
  : slugify(item.extracted.title_de || item.extracted.title_en || 'post');

// Append refCode suffix for uniqueness
const slug = `${titleSlug}-${refCode}`;

return [{ json: { ...item, refCode, slug } }];

